CREATE TABLE projects (
  id TEXT PRIMARY KEY,
  slug TEXT NOT NULL UNIQUE,
  draft_meta_json TEXT NOT NULL CHECK(json_valid(draft_meta_json) AND length(draft_meta_json) <= 65536),
  draft_body_json TEXT NOT NULL CHECK(json_valid(draft_body_json) AND length(draft_body_json) <= 524288),
  draft_version INTEGER NOT NULL DEFAULT 1 CHECK(draft_version > 0),
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  deleted_at TEXT
);
INSERT INTO "projects" ("id","slug","draft_meta_json","draft_body_json","draft_version","created_at","updated_at","deleted_at") VALUES('vinut-coco-boba-label','vinut-coco-boba-label-system','{"categoryId":"illustrator","title":"Vinut Coco Boba — Label System","shortTitle":"Coco Boba Label","subtitle":"A production-ready label system balancing a playful character world with dense export information.","thumbnailAssetId":"seed-media-vinut-coco-boba-label","coverAssetId":"seed-media-vinut-coco-boba-label","tags":["packaging","label","vector","print","coco boba","vinut"],"tools":["Adobe Illustrator","Print production"],"role":"Packaging & label design","year":"Selected work","isFeatured":true,"sortOrder":10}','{"schemaVersion":1,"blocks":[{"id":"visual-system-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"01 / Visual system","italic":true}]}]},{"id":"visual-system-heading","type":"heading","level":2,"text":"One label, many layers of information"},{"id":"visual-system-copy","type":"text","paragraphs":[{"spans":[{"text":"The composition gives the character and Coco Boba name a clear center while nutritional, legal and production information remain organized around it."}]}]},{"id":"visual-system-media","type":"image","assetId":"seed-media-vinut-coco-boba-label","alt":"Vinut Coco Boba coconut milk tea label artwork and print production sheet","fit":"contain"},{"id":"production-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"02 / Production","italic":true}]}]},{"id":"production-heading","type":"heading","level":2,"text":"Prepared for real packaging work"},{"id":"production-copy","type":"text","paragraphs":[{"spans":[{"text":"Color channels, dimensions, print status and artwork variants are presented as part of the working file rather than hidden behind a decorative mockup."}]}]}]}',1,'2026-09-11T00:00:00.000Z','2026-09-11T00:00:00.000Z',NULL);
INSERT INTO "projects" ("id","slug","draft_meta_json","draft_body_json","draft_version","created_at","updated_at","deleted_at") VALUES('coco-boba-tini-world','coco-boba-tini-world','{"categoryId":"photoshop","title":"Coco Boba — Tini World","shortTitle":"Tini World","subtitle":"A bright product campaign that turns the beverage can into the center of a miniature brand world.","thumbnailAssetId":"seed-media-coco-boba-poster","coverAssetId":"seed-media-coco-boba-poster","tags":["photoshop","campaign","poster","compositing","beverage","coco boba"],"tools":["Adobe Photoshop","Art direction"],"role":"Campaign visual & compositing","year":"2024","isFeatured":false,"sortOrder":20}','{"schemaVersion":1,"blocks":[{"id":"campaign-world-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"01 / Campaign world","italic":true}]}]},{"id":"campaign-world-heading","type":"heading","level":2,"text":"A product large enough to become a place"},{"id":"campaign-world-copy","type":"text","paragraphs":[{"spans":[{"text":"The can anchors the scene while storefronts, characters and small details build a playful world around the product without losing brand recognition."}]}]},{"id":"campaign-world-media","type":"image","assetId":"seed-media-coco-boba-poster","alt":"Coco Boba Tini World campaign poster with a coconut milk tea can and miniature storefront","fit":"cover"},{"id":"hierarchy-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"02 / Composition","italic":true}]}]},{"id":"hierarchy-heading","type":"heading","level":2,"text":"Fast recognition from top to bottom"},{"id":"hierarchy-copy","type":"text","paragraphs":[{"spans":[{"text":"Launch messaging leads into the hero can, then the eye lands on the product family and milk-tea proposition at the bottom of the poster."}]}]}]}',1,'2026-09-11T00:00:00.000Z','2026-09-11T00:00:00.000Z',NULL);
INSERT INTO "projects" ("id","slug","draft_meta_json","draft_body_json","draft_version","created_at","updated_at","deleted_at") VALUES('nam-viet-exhibition','nam-viet-group-exhibition-booth','{"categoryId":"blender","title":"Nam Viet Group — Exhibition Booth","shortTitle":"Exhibition Booth","subtitle":"A product-led exhibition environment designed to present a broad beverage portfolio from one clear viewpoint.","thumbnailAssetId":"seed-media-nam-viet-group-booth","coverAssetId":"seed-media-nam-viet-group-booth","tags":["3d","blender","booth","exhibition","beverage","nam viet"],"tools":["3D visualization","Spatial design"],"role":"Exhibition environment","year":"Selected work","isFeatured":false,"sortOrder":30}','{"schemaVersion":1,"blocks":[{"id":"space-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"01 / Environment","italic":true}]}]},{"id":"space-heading","type":"heading","level":2,"text":"A compact stage for a large product family"},{"id":"space-copy","type":"text","paragraphs":[{"spans":[{"text":"The booth uses a strong green-and-white silhouette, illuminated product walls and a clear central counter to stay recognizable across a busy exhibition floor."}]}]},{"id":"space-media","type":"image","assetId":"seed-media-nam-viet-group-booth","alt":"Nam Viet Group exhibition booth concept with beverage displays and green branding","fit":"cover"},{"id":"navigation-eyebrow","type":"text","paragraphs":[{"spans":[{"text":"02 / Visitor flow","italic":true}]}]},{"id":"navigation-heading","type":"heading","level":2,"text":"Products remain visible from the aisle"},{"id":"navigation-copy","type":"text","paragraphs":[{"spans":[{"text":"Large campaign graphics establish the brand at a distance while lower displays bring physical products into reach as visitors approach."}]}]}]}',1,'2026-09-11T00:00:00.000Z','2026-09-11T00:00:00.000Z',NULL);
